___CSS_LOADER_EXPORT___.push([module.id, "\n.font-custom{\n    font-size:15px !important\n}\n", "",{"version":3,"sources":["webpack://./modules/Report/Resources/assets/js/components/DataTableCommercialAnalysis.vue"],"names":[],"mappings":";AAgGA;IACA;AACA","sourcesContent":["<template>\n    <div>\n        <div class=\"row\">\n\n            <div class=\"col-md-12 col-lg-12 col-xl-12 \">\n                  <div class=\"row\">\n                    <div class=\"col-lg-8 col-md-8 mb-2\">\n                        <div class=\"form-group filter-content\"> \n                            <el-button\n                                type=\"secondary\"\n                                class=\"btn-show-filter mb-2\"\n                                :class=\"{ shift: see_more }\"\n                                @click=\"clickSeeMore\"\n                            >\n                                {{ see_more ? \"Ocultar filtros\" : \"Mostrar filtros\" }}\n                        </el-button>\n                        </div>\n                    </div> \n                </div>\n                <div class=\"row mt-2\" v-if=\"see_more\"> \n                    <div class=\"col-lg-4 col-md-4\">\n                        <div class=\"form-group\"  >\n                            <label class=\"control-label\">RUC Cliente</label> \n                            <el-input placeholder=\"Ingresar\"\n                                v-model=\"form.number\">\n                            </el-input>\n                        </div>\n                    </div> \n                    <div class=\"col-lg-4 col-md-4 \">\n                        <div class=\"form-group\"> \n                            <label class=\"control-label\">Tipo cliente</label>\n                            <el-select v-model=\"form.person_type_id\" filterable clearable>\n                                <el-option v-for=\"option in person_types\" :key=\"option.id\" :value=\"option.id\" :label=\"option.description\"></el-option>\n                            </el-select>\n                        </div>\n                    </div> \n                    \n                    <div class=\"col-lg-4 col-md-4 col-sm-4 pb-2\">\n                        <div class=\"form-group\"  >\n                            <label class=\"control-label\">Tipo producto</label>\n                            <el-select v-model=\"form.category_id\" filterable clearable>\n                                <el-option v-for=\"option in categories\" :key=\"option.id\" :value=\"option.id\" :label=\"option.name\"></el-option>\n                            </el-select> \n                        </div>\n                    </div>      \n                    \n                </div>\n                <div class=\"row mt-1 mb-3\">\n                    \n                    <div class=\"col-lg-9 col-md-9 col-md-9 col-sm-12\" style=\"margin-top:29px\"> \n                        <el-button class=\"submit\" type=\"primary\" @click.prevent=\"getRecordsByFilter\" :loading=\"loading_submit\" icon=\"el-icon-search\" >Buscar</el-button>\n                        \n                        <template v-if=\"records.length>0\"> \n                            <el-button class=\"submit\" type=\"success\" @click.prevent=\"clickDownload('excel')\"><i class=\"fa fa-file-excel\" ></i>  Exportal Excel</el-button>\n                        </template>\n\n                    </div>     \n                </div> \n            </div>\n            <div class=\"row mt-2\">  \n\n            </div>\n                <div class=\"row mt-1 mb-4\">\n                    \n                </div> \n            </div>\n\n            <div class=\"col-md-12\">\n                <div class=\"scroll-shadow shadow-left\" v-show=\"showLeftShadow\"></div>\n                <div class=\"scroll-shadow shadow-right\" v-show=\"showRightShadow\"></div>\n                <div class=\"table-responsive\" ref=\"scrollContainer\">\n                    <table class=\"table\">\n                        <thead>\n                            <slot name=\"heading\">sds sdsd</slot>\n                      \n                        </thead>\n                        <tbody>\n                            <slot v-for=\"(row, index) in records\" :row=\"row\" :index=\"customIndex(index)\"></slot>\n                        </tbody> \n                    </table>\n                    <div>\n                        <el-pagination\n                                @current-change=\"getRecords\"\n                                layout=\"total, prev, pager, next\"\n                                :total=\"pagination.total\"\n                                :current-page.sync=\"pagination.current_page\"\n                                :page-size=\"pagination.per_page\">\n                        </el-pagination>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n    </div>\n</template>\n<style>\n.font-custom{\n    font-size:15px !important\n}\n</style>\n<script>\n\n    import moment from 'moment'\n    import queryString from 'query-string'\n\n    export default { \n        props: {\n            resource: String,\n        },\n        data () {\n            return {\n                loading_submit:false,\n                columns: [],\n                records: [],\n                headers: headers_token,\n                document_types: [],\n                pagination: {}, \n                see_more:false,\n                search: {}, \n                totals: {}, \n                establishment: null,\n                establishments: [],       \n                person_types: [],       \n                categories: [],       \n                form: {},\n                pickerOptionsDates: {\n                    disabledDate: (time) => {\n                        time = moment(time).format('YYYY-MM-DD')\n                        return this.form.date_start > time\n                    }\n                },\n                pickerOptionsMonths: {\n                    disabledDate: (time) => {\n                        time = moment(time).format('YYYY-MM')\n                        return this.form.month_start > time\n                    }\n                },\n                showLeftShadow: false,\n                showRightShadow: false,\n            }\n        },\n        computed: {\n        },\n        created() {\n            this.initForm()\n            this.initTotals()\n            this.$eventHub.$on('reloadData', () => {\n                this.getRecords()\n            })\n        },\n        async mounted () { \n\n            \n            await this.$http.get(`/${this.resource}/data_table`).then((response) => {\n                this.categories = response.data.categories\n                this.person_types = response.data.person_types \n\n            });\n\n            await this.$http.get(`/${this.resource}/filter`)\n                .then(response => {\n                    this.establishments = response.data.establishments;\n                    this.document_types = response.data.document_types;\n                    // this.form.establishment_id = (this.establishments.length > 0)?this.establishments[0].id:null;\n                });\n\n\n            await this.getRecords()\n            // await this.getTotals()\n\n            this.$nextTick(() => {\n                const el = this.$refs.scrollContainer;\n                if (el) {\n                    el.addEventListener('scroll', this.checkScrollShadows);\n                    this.checkScrollShadows();\n                }\n            });\n\n        },\n        methods: { \n            checkScrollShadows() {\n                const el = this.$refs.scrollContainer;\n                if (!el) return;\n                \n                const scrollLeft = el.scrollLeft;\n                const scrollRight = el.scrollWidth - el.clientWidth - scrollLeft;\n                \n                this.showLeftShadow = scrollLeft > 1;\n                this.showRightShadow = scrollRight > 1;\n            },\n            clickSeeMore(){\n                this.see_more = (this.see_more) ? false : true\n            }, \n            clickDownload(type) {                 \n                let query = queryString.stringify({\n                    ...this.form\n                });\n                window.open(`/${this.resource}/${type}/?${query}`, '_blank');\n            },\n            initForm(){\n \n                this.form = {\n                    category_id: null,\n                    person_type_id:null,\n                    number:null,  \n                }\n\n            }, \n            initTotals(){\n                \n                this.totals = {\n                    acum_total_taxed : 0,\n                    acum_total_igv : 0,\n                    acum_total : 0,      \n                    acum_total_exonerated : 0,\n                    acum_total_unaffected : 0,         \n                    acum_total_free : 0,\n\n                    acum_total_taxed_usd : 0,\n                    acum_total_igv_usd : 0,\n                    acum_total_usd : 0,\n                }\n            },\n            customIndex(index) {\n                return (this.pagination.per_page * (this.pagination.current_page - 1)) + index + 1\n            }, \n            async getRecordsByFilter(){\n\n                this.loading_submit = await true\n                await this.getRecords()\n                this.loading_submit = await false\n\n            },\n            getRecords() {\n                return this.$http.get(`/${this.resource}/records?${this.getQueryParameters()}`).then((response) => {\n                    this.records = response.data.data\n                    this.pagination = response.data.meta\n                    this.pagination.per_page = parseInt(response.data.meta.per_page)\n                    this.loading_submit = false\n                    // this.initTotals()\n                    if(this.resource == 'reports/sales') this.getTotals(response.data.data)\n                });\n\n\n            },\n            getQueryParameters() {\n                return queryString.stringify({\n                    page: this.pagination.current_page,\n                    limit: this.limit,\n                    ...this.form\n                })\n            },\n            \n            changeDisabledDates() {\n                if (this.form.date_end < this.form.date_start) {\n                    this.form.date_end = this.form.date_start\n                }\n                // this.loadAll();\n            },\n            changeDisabledMonths() {\n                if (this.form.month_end < this.form.month_start) {\n                    this.form.month_end = this.form.month_start\n                }\n                // this.loadAll();\n            },\n            changePeriod() {\n                if(this.form.period === 'month') {\n                    this.form.month_start = moment().format('YYYY-MM');\n                    this.form.month_end = moment().format('YYYY-MM');\n                }\n                if(this.form.period === 'between_months') {\n                    this.form.month_start = moment().startOf('year').format('YYYY-MM'); //'2019-01';\n                    this.form.month_end = moment().endOf('year').format('YYYY-MM');;\n                }\n                if(this.form.period === 'date') {\n                    this.form.date_start = moment().format('YYYY-MM-DD');\n                    this.form.date_end = moment().format('YYYY-MM-DD');\n                }\n                if(this.form.period === 'between_dates') {\n                    this.form.date_start = moment().startOf('month').format('YYYY-MM-DD');\n                    this.form.date_end = moment().endOf('month').format('YYYY-MM-DD');\n                }\n                // this.loadAll();\n            },\n        }\n    }\n</script>"],"sourceRoot":""}]);
// Exports
/* harmony default export */ const __WEBPACK_DEFAULT_EXPORT__ = (___CSS_LOADER_EXPORT___);


